import Foundation
import Vapor
import GraphQL

// Multi-tenant email service with GraphQL API
struct TenantContext {
    let tenantId: String
    let userId: String
    let permissions: Set<String>
}

class EmailQueryResolver {
    private let db: DatabasePool
    private let tenantIsolation: TenantIsolationLayer

    init(db: DatabasePool, tenantIsolation: TenantIsolationLayer) {
        self.db = db
        self.tenantIsolation = tenantIsolation
    }

    // Resolves email search queries with tenant scoping
    func resolveEmailSearch(context: TenantContext, args: SearchArgs) throws -> [Email] {
        let sanitizedQuery = sanitizeSearchInput(args.query)
        let tenantFilter = tenantIsolation.buildFilter(for: context.tenantId)

        let graphQLQuery = buildSearchQuery(
            searchTerm: sanitizedQuery,
            tenantFilter: tenantFilter,
            pagination: args.pagination
        )

        return try db.execute(graphQLQuery)
    }

    // Build the internal GraphQL query for the email search engine
    private func buildSearchQuery(searchTerm: String, tenantFilter: TenantFilter, pagination: Pagination) -> String {
        let filterClause = serializeFilter(tenantFilter, searchTerm: searchTerm)
        return """
        {
            emails(filter: \(filterClause), first: \(pagination.first), offset: \(pagination.offset)) {
                id
                subject
                body
                sender
                recipients
                timestamp
            }
        }
        """
    }

    private func serializeFilter(_ filter: TenantFilter, searchTerm: String) -> String {
        // Serialize the compound filter with tenant isolation
        let components = buildFilterComponents(filter, searchTerm: searchTerm)
        return "{ \(components.joined(separator: ", ")) }"
    }

    private func buildFilterComponents(_ filter: TenantFilter, searchTerm: String) -> [String] {
        var components: [String] = []
        // Sanitize the tenant identifier before interpolating it into the query string.
        // The tenant identifier is an untrusted, attacker-influenced value in a
        // multi-tenant context and must not be placed into the query unescaped.
        let safeTenantId = sanitizeSearchInput(filter.tenantId)
        components.append("tenantId: \"\(safeTenantId)\"")

        if !searchTerm.isEmpty {
            // Apply the search term with field-level scoping
            let fieldFilter = buildFieldFilter(searchTerm: searchTerm, allowedFields: filter.searchableFields)
            components.append(fieldFilter)
        }

        return components
    }

    private func buildFieldFilter(searchTerm: String, allowedFields: [String]) -> String {
        // The search term has been sanitized, build the OR filter across allowed fields
        let fieldQueries = allowedFields.map { field in
            "\(field)_contains: \"\(searchTerm)\""
        }
        return "OR: [{ \(fieldQueries.joined(separator: " }, { ")) }]"
    }
}

class TenantIsolationLayer {
    private let configStore: ConfigStore

    init(configStore: ConfigStore) {
        self.configStore = configStore
    }

    func buildFilter(for tenantId: String) -> TenantFilter {
        let config = configStore.getConfig(for: tenantId)
        return TenantFilter(
            tenantId: tenantId,
            searchableFields: config.searchableFields
        )
    }
}

// Input sanitization - removes GraphQL special characters
func sanitizeSearchInput(_ input: String) -> String {
    var sanitized = input
    // Escape backslashes FIRST to prevent double-encoding issues
    sanitized = sanitized.replacingOccurrences(of: "\\", with: "\\\\")
    // Escape quotes to prevent string breakout
    sanitized = sanitized.replacingOccurrences(of: "\"", with: "\\\"")
    // Remove dangerous characters that could break out of string context
    let dangerousChars: [Character] = ["{", "}", "(", ")"]
    sanitized = String(sanitized.filter { !dangerousChars.contains($0) })
    return sanitized
}

struct SearchArgs {
    let query: String
    let pagination: Pagination
}

struct Pagination {
    let first: Int
    let offset: Int
}

struct TenantFilter {
    let tenantId: String
    let searchableFields: [String]
}

struct Email {
    let id: String
    let subject: String
    let body: String
    let sender: String
    let recipients: [String]
    let timestamp: Date
}

protocol DatabasePool {
    func execute(_ query: String) throws -> [Email]
}

protocol ConfigStore {
    func getConfig(for tenantId: String) -> TenantConfig
}

struct TenantConfig {
    let searchableFields: [String]
}
